from typing import Optional

class Solution:
    def findBottomLeftValue(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0  # handle empty tree if needed
        q = deque([root])
        leftmost = None
        while q:
            level_len = len(q)
            for i in range(level_len):
                node = q.popleft()
                if i == 0:          # first node of this level
                    leftmost = node.val
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
        return leftmost

