class Solution:
    def numberOfArrays(self, s: str, k: int) -> int:
        n = len(s)
        mod = 10**9 + 7

        from functools import lru_cache

        @lru_cache(None)
        def rec(i: int) -> int:
            # Base case: reached the end -> one way
            if i == n:
                return 1
            # Leading zero not allowed
            if s[i] == '0':
                return 0

            res = 0
            num = 0
            for j in range(i, n):
                # Build the number digit by digit to avoid costly int conversion
                num = num * 10 + (ord(s[j]) - ord('0'))
                if num > k:
                    break
                # Add ways starting from the next position
                res = (res + rec(j + 1)) % mod
            return res

        return rec(0)

