            for di, dj in ((-1, 0), (0, -1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1:
                    dfs(ni, nj)
        dfs(m - 1, n - 1)

        # BFS forward from start to end using only down/right moves
        dq = deque([(0, 0)])
        grid[0][0] = 0
        for di, dj in ((1, 0), (0, 1)):
            while dq:
                i, j = dq.popleft()
                if i == m - 1 and j == n - 1:
                    return True
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 2:
                    dq.append((ni, nj))
                    grid[ni][nj] = 0
        return False

