class Solution:
    def countPoints(self, rings: str) -> int:
        seen = []          # rods already processed
        count = 0
        # iterate over rod indices (every second character)
        for i in range(1, len(rings), 2):
            rod = rings[i]
            if rod not in seen:
                seen.append(rod)
                colors = set()
                # collect colors present on this rod
                for j in range(1, len(rings), 2):
                    if rings[j] == rod:
                        color = rings[j-1]
                        if color in ('R', 'G', 'B'):
                            colors.add(color)
                # count only if all three colors are present
                if len(colors) == 3:
                    count += 1
        return count

