import collections
class Solution:
    def isTransformable(self, s: str, t: str) -> bool:
        from collections import defaultdict, deque
        # map each digit to the queue of its positions in s
        pos = defaultdict(deque)
        for i, ch in enumerate(s):
            pos[int(ch)].append(i)

        # t must use only digits that appear in s
        for ch in t:
            if int(ch) not in pos:
                return False

        # simulate building t from left to right
        for ch in t:
            d = int(ch)
            # index of the next unused occurrence of digit d in s
            cur = pos[d].popleft()
            # if any smaller digit still has a leftmost index before cur, we cannot move d forward
            for smaller in range(d):
                if pos[smaller] and pos[smaller][0] < cur:
                    return False
            # clean up empty queues
            if not pos[d]:
                del pos[d]

        return True

