from typing import List

class Solution:
    def powerfulIntegers(self, x: int, y: int, bound: int) -> List[int]:
        if bound <= 0:
            return []
        def powers(v):
            yield 1
            if v == 1:
                return
            val = v
            while val <= bound:
                yield val
                val *= v
        result = set()
        for xi in powers(x):
            for yi in powers(y):
                s = xi + yi
                if s <= bound:
                    result.add(s)
        return list(result)

